<template>
  <main class="address-page">
    <ModuleHeader :title="tr('Endereços e envios')">
      <button class="primary erp-button erp-button--primary" @click="newAddress">
        <Plus :size="17" />
        {{ tr("Novo endereço") }}
      </button>
    </ModuleHeader>
    <div v-if="error" role="alert" class="alert error">{{ tr(error) }}<button class="erp-button erp-button--ghost erp-button--icon" @click="error=''">×</button></div><div v-if="notice" role="status" class="alert success">{{ tr(notice) }}<button class="erp-button erp-button--ghost erp-button--icon" @click="notice=''">×</button></div>
    <section class="metrics"><article><MapPin/><span>{{ tr('Endereços salvos') }}</span><strong>{{ overview.addresses }}</strong></article><article><Printer/><span>{{ tr('Na fila de impressão') }}</span><strong>{{ overview.statuses.pending || 0 }}</strong></article><article><CheckCircle2/><span>{{ tr('Enviados à impressora') }}</span><strong>{{ overview.statuses.submitted || 0 }}</strong></article><article><Activity/><span>{{ tr('Computador da loja') }}</span><strong class="connection">{{ online ? tr('Conectado') : tr('Sem conexão recente') }}</strong><small>{{ activeDevice?.name || tr('Nenhuma impressora ativa') }}</small></article></section>
    <nav class="tabs" :aria-label="tr('Gestão de endereços')"><button class="erp-control" v-for="t in tabs" :key="t.id" :class="{selected:tab===t.id}" @click="changeTab(t.id)"><component :is="t.icon" :size="17"/>{{tr(t.label)}}</button></nav>
    <section v-if="tab==='addresses'" class="panel"><div class="section-head"><div><h2>{{ tr('Agenda de endereços') }}</h2><p>{{ tr('Um cadastro por destinatário e endereço, com histórico de todas as utilizações.') }}</p></div><span class="count">{{ addresses.total }} {{ tr('registros') }}</span></div><form class="toolbar" @submit.prevent="offset=0;loadAddresses()"><div class="search"><Search :size="17"/><input v-model="query" :placeholder="tr('Buscar nome, cidade, telefone…')" :aria-label="tr('Buscar endereços')"/></div><select v-model="country" :aria-label="tr('País')" @change="offset=0;loadAddresses()"><option value="">{{ tr('Todos os países') }}</option><option value="BR">{{ tr('Brasil') }}</option><option value="PY">{{ tr('Paraguai') }}</option></select><select v-model="showActive" :aria-label="tr('Situação')" @change="offset=0;loadAddresses()"><option :value="true">{{ tr('Ativos') }}</option><option :value="false">{{ tr('Arquivados') }}</option></select><button class="erp-button erp-button--secondary" type="submit">{{ tr('Buscar') }}</button></form>
      <p v-if="customerFilter" class="hint">{{ tr('Filtrando endereços deste cliente.') }} <button class="erp-button erp-button--secondary" @click="customerFilter='';loadAddresses()">{{ tr('Mostrar todos') }}</button></p>
      <div v-if="loading" class="empty">{{ tr('Carregando endereços…') }}</div>
      <div v-else-if="!addresses.items.length" class="empty" role="status">
        <MapPin :size="36"/>
        <template v-if="addressFiltersApplied">
          <h3>{{ tr('Nenhum endereço encontrado') }}</h3>
          <p>{{ tr('Nenhum endereço corresponde aos filtros aplicados.') }}</p>
          <button class="erp-button erp-button--secondary" @click="clearAddressFilters">{{ tr('Limpar filtros') }}</button>
        </template>
        <template v-else>
          <h3>{{ tr('Nenhum endereço aqui ainda') }}</h3>
          <p>{{ tr('Cadastre um destinatário ou salve uma impressão do histórico.') }}</p>
          <button class="erp-button erp-button--secondary" @click="newAddress">{{ tr('Cadastrar endereço') }}</button>
        </template>
      </div>
      <div v-else class="address-grid"><article v-for="a in addresses.items" :key="a.id" class="address-card"><div class="card-top"><span class="country">{{a.data.pais==='BR'?tr('BR · Brasil'):tr('PY · Paraguai')}}</span><span v-if="a.cliente_id||a.pdv_cliente_id" class="linked"><Users :size="13"/> {{ a.cliente_nome || tr('Cliente vinculado') }}</span></div><p v-if="a.customer_link_review" class="hint">{{ tr('Confira o vínculo do cliente: nome incompleto ou dados divergentes.') }}</p><h3>{{a.label}}</h3><strong>{{a.data.nome || tr('Sem nome informado')}}</strong><p>{{[a.data.endereco,a.data.numero,a.data.bairro,a.data.complemento].filter(Boolean).join(', ') || tr('Sem rua informada')}}</p><p>{{[a.data.cidade,a.data.estado,a.data.cep].filter(Boolean).join(' · ')}}</p><small>{{a.data.telefone || tr('Sem telefone')}}</small><div class="card-actions"><button class="erp-button erp-button--secondary erp-button--sm" @click="openAddressUsage(a)"><History :size="15"/>{{ tr('Histórico') }}</button><button class="erp-button erp-button--secondary erp-button--sm" @click="editAddress(a)"><Pencil :size="15"/>{{ tr('Editar') }}</button><button class="erp-button erp-button--secondary erp-button--sm" v-if="a.active" @click="openPrint(a)"><Printer :size="15"/>{{ tr('Imprimir') }}</button><button class="erp-button erp-button--secondary erp-button--sm" v-if="a.active && a.data.pais==='BR'" @click="openFreight(a)"><Truck :size="15"/>{{ tr('Frete') }}</button></div></article></div><div class="pagination"><button class="erp-button erp-button--secondary" :disabled="offset===0" @click="offset-=30;loadAddresses()">{{ tr('Anterior') }}</button><span>{{addresses.items.length ? offset+1 : 0}}–{{addresses.items.length ? Math.min(offset+addresses.items.length,addresses.total) : 0}} {{ tr('de') }} {{addresses.total}}</span><button class="erp-button erp-button--secondary" :disabled="offset+30>=addresses.total" @click="offset+=30;loadAddresses()">{{ tr('Próxima') }}</button></div>
    </section>
    <section v-if="tab==='history'" class="panel"><div class="section-head"><div><h2>{{ tr('Histórico de impressões') }}</h2><p>{{ tr('Inclui solicitações do ERP e do bot. Enviado à impressora não confirma a saída física do papel.') }}</p></div><button class="erp-button erp-button--secondary" @click="loadHistory"><RefreshCw :size="16"/>{{ tr('Atualizar') }}</button></div><form class="toolbar" @submit.prevent="historyOffset=0;loadHistory()"><input v-model="historyQuery" :placeholder="tr('Buscar destinatário…')" :aria-label="tr('Buscar histórico')"/><select v-model="historyStatus" :aria-label="tr('Estado da impressão')" @change="historyOffset=0;loadHistory()"><option value="">{{ tr('Todos os estados') }}</option><option v-for="(label,key) in states" :key="key" :value="key">{{tr(label)}}</option></select><button class="erp-button erp-button--secondary">{{ tr('Buscar') }}</button></form><div class="table-wrap"><table><thead><tr><th>{{ tr('Destinatário') }}</th><th>{{ tr('Solicitação') }}</th><th>{{ tr('Origem') }}</th><th>{{ tr('Estado') }}</th><th>{{ tr('Ações') }}</th></tr></thead><tbody><tr v-for="j in history.items" :key="j.id"><td><strong>{{j.recipient || tr('Sem nome')}}</strong><small>{{j.country}} {{j.parent_id?tr(' · Nova cópia'):''}}</small></td><td>{{date(j.created_at)}}<small>{{j.user}}</small></td><td>{{j.source==='bot'?tr('Assistente'):j.source==='superfrete'?tr('SuperFrete'):tr('ERP / arquivo')}}</td><td><span class="badge" :class="j.status">{{tr(states[j.status]||j.status)}}</span></td><td><div class="row-actions"><button class="erp-button erp-button--secondary erp-button--sm" v-if="j.pdf_available" @click="viewJob(j.id)">{{ tr('PDF') }}</button><button class="erp-button erp-button--secondary erp-button--sm" v-if="j.editable" @click="editJob(j)">{{ tr('Editar / nova cópia') }}</button><button class="erp-button erp-button--danger erp-button--sm" v-if="j.status==='pending'" @click="cancelJob(j.id)">{{ tr('Cancelar') }}</button></div></td></tr><tr v-if="!history.items.length"><td colspan="5" class="empty">{{ tr('Nenhuma impressão encontrada.') }}</td></tr></tbody></table></div><div class="pagination"><button class="erp-button erp-button--secondary" :disabled="historyOffset===0" @click="historyOffset-=30;loadHistory()">{{ tr('Anterior') }}</button><span>{{history.total}} {{ tr('impressões') }}</span><button class="erp-button erp-button--secondary" :disabled="historyOffset+30>=history.total" @click="historyOffset+=30;loadHistory()">{{ tr('Próxima') }}</button></div></section>
    <section v-if="tab==='senders'" class="panel"><div class="section-head"><div><h2>{{ tr('Remetentes e endereços base') }}</h2><p>{{ tr('Um único endereço para imprimir e emitir fretes.') }}</p></div><div class="row-actions"><button class="erp-button erp-button--secondary" v-if="auth.isOwner" @click="generatorOpen=true"><Sparkles :size="16"/>{{ tr('Gerar pessoa · 4Devs') }}</button><button class="erp-button erp-button--secondary" @click="newSender"><Plus :size="16"/>{{ tr('Novo remetente') }}</button></div></div><div class="address-grid"><article v-for="s in senders" :key="s.id" class="address-card"><span class="country">{{s.active?tr('Ativo'):tr('Arquivado')}}</span><span v-if="s.synthetic" class="synthetic-source">{{ tr('4Devs · origem sintética') }}</span><h3>{{s.name}}</h3><p class="preline">{{s.lines.join('\n')}}</p><small>{{senderReady(s)?tr('Endereço pronto para impressão e frete'):tr('Complete os campos faltantes para emitir frete')}}</small><button class="erp-button erp-button--secondary" @click="editSender(s)"><Pencil :size="15"/>{{ tr('Editar remetente') }}</button></article></div></section>
    <section v-if="tab==='layouts'" class="panel"><div class="section-head"><div><h2>{{ tr('Padrões de impressão') }}</h2><p>{{ tr('Modelos A4 usados pelo ERP e pelo bot. Mudanças valem para novas solicitações.') }}</p></div></div><div class="layout-grid"><form v-for="l in layouts" :key="l.id" class="layout-form" @submit.prevent="saveLayout(l)"><h3>{{l.name}}</h3><label>{{ tr('Título do bloco') }}<input v-model="l.config.title" maxlength="60"/></label><div class="form-grid"><label>{{ tr('Tamanho da fonte') }}<input v-model.number="l.config.font_size" type="number" min="10" max="24"/></label><label>{{ tr('Margem (pontos)') }}<input v-model.number="l.config.margin" type="number" min="20" max="80"/></label><label>{{ tr('Fonte do remetente') }}<input v-model.number="l.config.sender_font_size" type="number" min="9" max="20"/></label><label>{{ tr('Espaço do remetente') }}<input v-model.number="l.config.sender_gap" type="number" min="10" max="100"/></label></div><label class="check"><input v-model="l.config.bold" type="checkbox"/>{{ tr('Destinatário em negrito') }}</label><label>{{ tr('Campos e ordem') }}</label><div v-for="(field,index) in l.config.fields" :key="field" class="field-order"><span>{{tr(layoutFieldLabel(l,field))}}</span><button class="erp-button erp-button--ghost erp-button--icon" type="button" :disabled="index===0" @click="moveField(l,index,-1)" :aria-label="tr('Mover campo para cima')">↑</button><button class="erp-button erp-button--ghost erp-button--icon" type="button" :disabled="index===l.config.fields.length-1" @click="moveField(l,index,1)" :aria-label="tr('Mover campo para baixo')">↓</button><button class="erp-button erp-button--secondary" type="button" :disabled="l.config.fields.length===1" @click="l.config.fields.splice(index,1)">{{ tr('Ocultar') }}</button></div><select :aria-label="tr('Adicionar campo ao modelo')" @change="addField(l,$event)"><option value="">{{ tr('Adicionar campo…') }}</option><option v-for="(name,key) in fieldLabels" :key="key" :value="key" :disabled="l.config.fields.includes(key)">{{tr(layoutFieldLabel(l,key))}}</option></select><button class="primary erp-button erp-button--primary" :disabled="saving">{{ tr('Salvar padrão') }}</button></form></div></section>
    <section v-if="tab==='freight'" class="panel"><FreightAvailability :availability="freightStatus.availability" :restored="freightRestored" /><div class="section-head"><div><h2>{{ tr('Etiquetas SuperFrete') }}</h2><p>{{freightStatus.environment==='sandbox'?tr('Ambiente de testes: etiquetas sem validade para postagem.'):tr('Ambiente de produção: emissão utiliza saldo da sua conta.')}}</p></div><span v-if="!['checking','unknown'].includes(freightStatus.availability)" class="badge" :class="freightStatus.configured?'submitted':'pending'">{{freightStatus.configured?tr('Integração configurada'):tr('Configuração pendente')}}</span></div><p v-if="freightStatus.availability==='configuration' && !freightStatus.configured" class="hint">{{ tr('A integração precisa do token e do contato técnico no servidor. Seus endereços e impressões simples continuam disponíveis.') }}</p><div class="table-wrap"><table><thead><tr><th>{{ tr('Destinatário') }}</th><th>{{ tr('Data') }}</th><th>{{ tr('Estado') }}</th><th>{{ tr('Valor') }}</th><th>{{ tr('Rastreio / ações') }}</th></tr></thead><tbody><tr v-for="f in freights.items" :key="f.id"><td>{{f.recipient}}<small>{{f.environment==='sandbox'?tr('Teste'):tr('Produção')}}</small></td><td>{{date(f.created_at)}}</td><td>{{tr(freightStates[f.state]||f.state)}}<small v-if="f.label_status==='waiting'">{{ tr('PDF em processamento · atualização automática') }}</small><small v-if="f.print_job_id">{{ tr('Enviada à fila de impressão') }}</small><small v-if="f.recovery_check_at">{{tr('Próxima consulta automática:')}} {{date(f.recovery_check_at)}}</small><small v-if="f.error" class="danger">{{serviceMessage(f.error)}}</small></td><td>{{money(f.price)}}</td><td><div class="row-actions"><code>{{f.tracking}}</code><button class="erp-button erp-button--secondary" @click="selectedFreight=f;modal='freight-result'">{{ tr('Abrir') }}</button><button class="erp-button erp-button--secondary erp-button--sm" v-if="f.provider_id" :disabled="saving" @click="refreshFreight(f)">{{ tr('Consultar') }}</button></div></td></tr><tr v-if="!freights.items.length"><td colspan="5" class="empty">{{ tr('Selecione um endereço brasileiro e clique em Frete para começar.') }}</td></tr></tbody></table></div><div class="pagination"><button class="erp-button erp-button--secondary" :disabled="freightOffset===0" @click="freightOffset-=30;loadFreights()">{{ tr('Anterior') }}</button><span>{{freights.total}} {{ tr('cotações e fretes') }}</span><button class="erp-button erp-button--secondary" :disabled="freightOffset+30>=freights.total" @click="freightOffset+=30;loadFreights()">{{ tr('Próxima') }}</button></div></section>

    <div v-if="modal" class="overlay erp-dialog-backdrop" @click.self="closeModal"><section v-erp-dialog class="dialog erp-dialog erp-dialog--lg" :class="{'usage-dialog':modal==='address-usage'}" role="dialog" aria-modal="true" :aria-label="tr(modalTitle)"><header class="erp-dialog__header"><h2>{{tr(modalTitle)}}</h2><button data-dialog-close class="erp-button erp-button--secondary erp-button--icon" :disabled="saving" @click="closeModal" :aria-label="tr('Fechar')">×</button></header><p v-if="modalError" role="alert" class="alert error">{{tr(modalError)}}</p>
      <div v-if="modal==='address-usage'" class="erp-dialog__body"><AddressUsageHistory v-if="modal==='address-usage' && usageAddress" :key="usageAddress.id" :address="usageAddress" @freight="openUsageFreight" @print="viewJob"/></div>
      <form v-if="modal==='address' || modal==='print'" @submit.prevent="modal==='address'?saveAddress():submitPrint()" class="erp-dialog__form"><div class="erp-dialog__body"><label v-if="modal==='address'">{{ tr('Identificação do endereço') }}<input v-model="form.label" required maxlength="120" :placeholder="tr('Casa, trabalho, transportadora…')"/></label><div class="customer-box" v-if="modal==='address'"><label>{{ tr('Vincular a cliente existente') }}<input v-model="customerQuery" @input="searchCustomers" :placeholder="tr('Buscar nome ou telefone')"/></label><div class="suggestions"><button class="erp-control" type="button" v-for="c in customerResults" :key="c.kind+c.id" @click="linkCustomer(c)">{{c.nome}} · {{c.kind==='pdv'?tr('PDV'):tr('Pedidos')}}</button></div><p v-if="form.cliente_id||form.pdv_cliente_id">{{ tr('Cliente vinculado') }} {{linkedName}} <button class="erp-button erp-button--danger" type="button" @click="form.cliente_id=null;form.pdv_cliente_id=null;linkedName=''">{{ tr('Desvincular') }}</button></p></div><p v-if="modal==='address'" class="hint">{{ tr('Ao salvar, o endereço será associado a um cliente existente ou criará um novo cadastro.') }}</p><AddressFields v-model="form.data"/><label v-if="modal==='address'" class="check"><input v-model="form.active" type="checkbox"/>{{ tr('Endereço ativo') }}</label><template v-if="modal==='print'"><p class="hint">{{ tr('Uma folha A4, uma cópia.') }} {{form.data.pais==='PY'?tr('Paraguai: somente os dados enviados.'):tr('Brasil: destinatário e remetente selecionado.')}}</p><label v-if="form.data.pais==='BR'">{{ tr('Remetente') }}<select v-model="senderId" required><option value="">{{ tr('Selecione') }}</option><option v-for="s in activeSenders" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>{{ tr('Impressora') }}<select v-model="deviceId" required><option v-for="d in overview.devices.filter(d=>d.active)" :key="d.id" :value="d.id">{{d.name}}</option></select></label><button class="erp-button erp-button--secondary" type="button" :disabled="saving" @click="previewPrint">{{ tr('Conferir PDF') }}</button><a v-if="previewUrl" :href="previewUrl" :download="tr('endereco.pdf')" class="button erp-button erp-button--secondary">{{ tr('Baixar PDF para conferir') }}</a><iframe v-if="previewUrl" :src="previewUrl" :title="tr('Prévia de impressão')" class="pdf-preview"></iframe></template></div><footer class="erp-dialog__footer"><button class="erp-button erp-button--secondary" type="button" @click="closeModal">{{ tr('Voltar') }}</button><button class="erp-button erp-button--secondary" v-if="modal==='print'" type="button" @click="modal='address';form.id='';form.version=1;form.label=form.data.nome || 'Endereço'">{{ tr('Salvar na agenda') }}</button><button class="primary erp-button erp-button--primary" :disabled="saving">{{saving?tr('Salvando…'):modal==='address'?tr('Salvar endereço'):tr('Enviar à impressora')}}</button></footer></form>
      <form v-if="modal==='sender'" @submit.prevent="saveSender" class="erp-dialog__form"><div class="erp-dialog__body"><p v-if="senderForm.synthetic" class="hint">{{ tr('Origem sintética · 4Devs. Este cadastro foi aprovado manualmente; os dados não comprovam identidade. A origem é preservada após a edição.') }}</p><label>{{ tr('Identificação no gestor') }}<input v-model="senderForm.name" required maxlength="100"/></label><details v-if="senderForm.id"><summary>{{ tr('Consultar bloco salvo anteriormente') }}</summary><p class="preline">{{senderForm.lines.join('\n')}}</p></details><label>{{ tr('Prévia do remetente impresso') }}<textarea :value="senderBlock.join('\n')" rows="7" readonly></textarea></label><label class="check"><input v-model="senderForm.active" type="checkbox"/>{{ tr('Remetente ativo') }}</label><h3>{{ tr('Endereço do remetente — impressão e SuperFrete') }}</h3><p class="hint">{{ tr('Impressão e SuperFrete usam o mesmo endereço. Edite os campos abaixo: a prévia de impressão será atualizada junto. Recuperamos os dados reconhecidos nos blocos antigos; confira e complete apenas o que faltar. Pelo bot, você também pode complementar os dados na conversa.') }}</p><AddressFields v-model="senderData" :name-label="tr('Nome do remetente')"/></div><footer class="erp-dialog__footer"><button class="erp-button erp-button--secondary" type="button" @click="closeModal">{{ tr('Voltar') }}</button><button class="primary erp-button erp-button--primary" :disabled="saving">{{ tr('Salvar remetente') }}</button></footer></form>
      <form v-if="modal==='freight'" @submit.prevent="quoteFreight" class="erp-dialog__form"><div class="erp-dialog__body"><p>{{ tr('Destino:') }} <strong>{{form.label}}</strong>{{ tr('. Os dados de frete precisam estar completos no endereço e no remetente.') }}</p><label>{{ tr('Remetente') }}<select v-model="senderId" required><option value="">{{ tr('Selecione') }}</option><option v-for="s in activeSenders" :key="s.id" :value="s.id">{{s.name}}</option></select></label><div class="form-grid"><label v-for="(name,key) in packageLabels" :key="key">{{tr(name)}}<input v-model.number="packageForm[key]" type="number" step="0.01" min="0.01" required/></label></div><h3>{{ tr('Conteúdo do pacote') }}</h3><div class="product-row" v-for="(p,i) in products" :key="i"><input v-model="p.name" :aria-label="tr('Produto')" :placeholder="tr('Produto')" required/><input v-model.number="p.quantity" :aria-label="tr('Quantidade')" type="number" min="1" required/><input v-model="p.unitary_value" :aria-label="tr('Valor unitário em reais')" type="number" min="0" step="0.01" required/><button class="erp-button erp-button--danger erp-button--icon" type="button" :disabled="products.length===1" @click="products.splice(i,1)">×</button></div><button class="erp-button erp-button--secondary" type="button" @click="products.push({name:'',quantity:1,unitary_value:'0.00'})">{{ tr('Adicionar produto') }}</button><label class="check"><input v-model="nonCommercial" type="checkbox"/>{{ tr('Envio não comercial com declaração de conteúdo') }}</label><label v-if="!nonCommercial">{{ tr('Chave da nota fiscal') }}<input v-model="invoice" pattern="[0-9]{44}" maxlength="44" required/></label><p class="hint">{{ tr('Informe peso e medidas reais. Cotar não realiza pagamento.') }}</p></div><footer class="erp-dialog__footer"><button class="erp-button erp-button--secondary" type="button" @click="closeModal">{{ tr('Voltar') }}</button><button class="primary erp-button erp-button--primary" :disabled="saving || !freightStatus.configured">{{saving?tr('Consultando…'):tr('Cotar frete')}}</button></footer></form>
      <div v-if="modal==='freight-result' && selectedFreight" class="erp-dialog__body"><p><strong>{{selectedFreight.recipient}}</strong> · {{tr(freightStates[selectedFreight.state]||selectedFreight.state)}}</p><p v-if="selectedFreight.environment==='sandbox'" class="hint">{{ tr('TESTE: esta etiqueta não serve para postagem.') }}</p><p v-for="warning in selectedFreight.postal_warnings || []" :key="warning" class="hint">{{serviceMessage(warning)}}</p><div v-if="selectedFreight.state==='quoted'" class="rates"><button class="erp-control" v-for="r in selectedFreight.rates" :key="r.id" :disabled="saving" @click="createCart(r.id)"><strong>{{r.name}}</strong><span>{{r.delivery_time}} {{ tr('dias estimados') }}</span><b>{{money(r.price)}}</b><small>{{ tr('Selecionar serviço') }}</small></button></div><div v-if="selectedFreight.state==='pending'" class="purchase"><h3>{{ tr('Conferir emissão') }}</h3><p>{{ tr('Valor da etiqueta:') }} <strong>{{money(selectedFreight.price)}}</strong></p><p>{{ tr('Ao confirmar, esse valor será debitado do saldo SuperFrete. O PDF será buscado automaticamente e enviado ao Telegram, se você estiver conectado ao bot.') }}</p><label class="check"><input v-model="autoPrintLabel" type="checkbox"/>{{ tr('Imprimir automaticamente quando o PDF estiver pronto') }}</label><button class="primary erp-button erp-button--primary" :disabled="saving" @click="payFreight">{{saving?tr('Processando…'):tr('Confirmar pagamento e emitir')}}</button></div><p v-if="selectedFreight.label_status==='waiting'" class="hint">{{ tr('Aguardando o PDF da SuperFrete. Esta tela será atualizada automaticamente; não é necessário pagar novamente.') }}</p><p v-if="selectedFreight.print_job_id" class="hint">{{ tr('Etiqueta enviada à fila da loja. Mantenha o Eleven Impressao aberto no Windows.') }}</p><p v-if="selectedFreight.label_error" class="hint">{{serviceMessage(selectedFreight.label_error)}}</p><p v-if="selectedFreight.recovery_check_at" class="hint">{{tr('Próxima consulta automática:')}} {{date(selectedFreight.recovery_check_at)}}</p><p v-if="selectedFreight.error" class="alert error">{{serviceMessage(selectedFreight.error)}}</p><p v-if="selectedFreight.tracking">{{ tr('Rastreio:') }} <strong>{{selectedFreight.tracking}}</strong></p><div class="row-actions"><button class="erp-button erp-button--secondary erp-button--sm" v-if="selectedFreight.provider_id" :disabled="saving" @click="refreshFreight(selectedFreight)">{{ tr('Consultar estado / obter PDF') }}</button><button class="erp-button erp-button--secondary" v-if="selectedFreight.pdf_available" @click="openLabelPdf">{{ tr('Baixar etiqueta PDF') }}</button><a v-else-if="selectedFreight.label_url" :href="selectedFreight.label_url" target="_blank" rel="noopener noreferrer" class="button erp-button erp-button--secondary">{{ tr('Abrir etiqueta PDF') }}</a><button class="erp-button erp-button--secondary" v-if="selectedFreight.pdf_available && !selectedFreight.print_job_id" :disabled="saving" @click="printLabel">{{ tr('Enviar etiqueta à impressora') }}</button></div></div>
    </section></div>
    <SenderGeneratorModal v-if="generatorOpen && auth.isOwner" @close="generatorOpen=false" @saved="generatedSenderSaved"/>
  </main>
</template>

<script setup lang="ts">
import { vErpDialog } from '@/directives/erpDialog'
import ModuleHeader from '@/components/ModuleHeader.vue'
import { computed,onMounted,onUnmounted,ref,watch } from 'vue'
import { useRoute } from 'vue-router'
import { Plus,MapPin,Printer,CheckCircle2,Activity,Search,Pencil,Users,Truck,RefreshCw,History,SlidersHorizontal,Sparkles } from 'lucide-vue-next'
import api from '@/services/api'
import { useAuthStore } from '@/stores/auth'
import { useAddressI18n } from '@/components/addresses/i18n'
import AddressFields from '@/components/addresses/AddressFields.vue'
import AddressUsageHistory from '@/components/addresses/AddressUsageHistory.vue'
import SenderGeneratorModal from '@/components/addresses/SenderGeneratorModal.vue'
import FreightAvailability from '@/components/addresses/FreightAvailability.vue'
import type { AddressData,SavedAddress,Sender,Layout,Job,Freight,Customer,Overview } from '@/components/addresses/types'
import { blankAddress } from '@/components/addresses/types'
const {tr,date,money,errorKey,serviceMessage}=useAddressI18n()
const auth=useAuthStore()
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const route=useRoute(),base='/api/address-manager'
const tabs=[{id:'addresses',label:'Endereços',icon:MapPin},{id:'history',label:'Impressões',icon:History},{id:'senders',label:'Remetentes',icon:Users},{id:'layouts',label:'Padrões',icon:SlidersHorizontal},{id:'freight',label:'SuperFrete',icon:Truck}]
const tab=ref('addresses'),loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),modalError=ref(''),modal=ref('')
const overview=ref<Overview>({addresses:0,statuses:{},devices:[]}),addresses=ref<{total:number;items:SavedAddress[]}>({total:0,items:[]}),history=ref<{total:number;items:Job[]}>({total:0,items:[]}),senders=ref<Sender[]>([]),layouts=ref<Layout[]>([]),freights=ref<{total:number;items:Freight[]}>({total:0,items:[]})
const query=ref(''),country=ref(''),showActive=ref(true),offset=ref(0),historyOffset=ref(0),historyQuery=ref(''),historyStatus=ref(''),freightOffset=ref(0),customerFilter=ref(String(route.query.customer_id||''))
const addressFiltersApplied=ref(false)
const activeDevice=computed(()=>overview.value.devices.find(d=>d.active)),online=computed(()=>!!activeDevice.value?.last_seen_at && Date.now()-new Date(activeDevice.value.last_seen_at).getTime()<90000),activeSenders=computed(()=>senders.value.filter(s=>s.active))
const emptyForm=():SavedAddress=>({id:'',label:'',data:blankAddress(),cliente_id:null,pdv_cliente_id:null,active:true,version:1})
const usageAddress=ref<SavedAddress|null>(null)
const form=ref(emptyForm()),senderId=ref(''),deviceId=ref(''),parentId=ref<string|null>(null),requestKey=ref(crypto.randomUUID()),previewUrl=ref(''),linkedName=ref(''),customerQuery=ref(''),customerResults=ref<Customer[]>([])
const generatorOpen=ref(false)
const senderForm=ref<Sender>({id:'',name:'',lines:[],data:null,active:true,version:1}),senderData=ref(blankAddress('BR'))
const labelRequestKeys=new Map<string,string>()
const senderBlock=computed(()=>{const d=senderData.value;return[d.nome||senderForm.value.name,[d.endereco,d.numero].filter(Boolean).join(', '),d.bairro,d.complemento,[d.cidade,d.estado].filter(Boolean).join(' - '),d.cep?'CEP '+d.cep:'',d.cpf?(d.pais==='PY'?'RUC/C.I: ':'CPF/CNPJ: ')+d.cpf:''].filter(Boolean)})
function senderReady(s:Sender){const d=s.data;return !!d&&d.pais==='BR'&&['nome','endereco','bairro','cidade','estado','cep'].every(k=>!!d[k as keyof AddressData])}
const autoPrintLabel=ref(true)
const freightRestored=ref(false)
const freightStatus=ref({configured:false,environment:'sandbox',availability:'checking'}),selectedFreight=ref<Freight|null>(null),packageForm=ref({weight:0,height:0,width:0,length:0}),products=ref([{name:'',quantity:1,unitary_value:'0.00'}]),nonCommercial=ref(false),invoice=ref('')
const packageLabels={weight:'Peso (kg)',height:'Altura (cm)',width:'Largura (cm)',length:'Comprimento (cm)'}
const fieldLabels:Record<string,string>={nome:'Nome',endereco:'Endereço',cidade:'Cidade / UF',cep:'CEP',pais:'País',telefone:'Telefone',cpf:'CPF'}
function layoutFieldLabel(layout:Layout,field:string){return field==='cpf' && layout.id==='py'?'RUC/C.I':fieldLabels[field]}
const states:Record<string,string>={pending:'Na fila',claimed:'Retirado pelo agente',submitted:'Enviado à impressora',uncertain:'Conferir no Windows',failed:'Falha',expired:'Expirado',cancelled:'Cancelado'}
const freightStates:Record<string,string>={quoting:'Consultando cotação',retry_waiting:'Aguardando recuperação automática',rejected:'Dados ou conta precisam de correção',quoted:'Cotado',creating:'Criando frete',pending:'Aguardando pagamento',paying:'Pagamento em andamento',released:'Etiqueta emitida',posted:'Postado',delivered:'Entregue',cancelled:'Cancelado',uncertain:'Conferência necessária'}
const modalTitle=computed(()=>({'address':form.value.id?'Editar endereço':'Novo endereço','print':'Conferir impressão','sender':'Remetente','freight':'Cotar envio','freight-result':'Etiqueta SuperFrete','address-usage':'Histórico de utilização'}[modal.value]||''))
function explain(e:unknown){return errorKey(e)}
async function act(fn:()=>Promise<void>){saving.value=true;modalError.value='';error.value='';try{await fn()}catch(e){if(modal.value)modalError.value=explain(e);else error.value=explain(e)}finally{saving.value=false}}
async function loadAddresses(){
  loading.value=true
  const params={q:query.value,country:country.value,active:showActive.value,offset:offset.value,customer_id:customerFilter.value||undefined}
  try{
    addresses.value=(await api.get(base+'/addresses',{params})).data
    addressFiltersApplied.value=!!(params.q.trim() || params.country || !params.active || params.customer_id)
  }catch(e){error.value=explain(e)}finally{loading.value=false}
}
function clearAddressFilters(){query.value='';country.value='';showActive.value=true;customerFilter.value='';offset.value=0;void loadAddresses()}
async function loadHistory(){try{history.value=(await api.get(base+'/history',{params:{q:historyQuery.value,status:historyStatus.value,offset:historyOffset.value}})).data}catch(e){error.value=explain(e)}}
async function loadFreights(){void loadFreightStatus();try{freights.value=(await api.get('/api/freight/orders',{params:{offset:freightOffset.value}})).data;if(selectedFreight.value){const updated=freights.value.items.find(f=>f.id===selectedFreight.value!.id);if(updated)selectedFreight.value=updated}}catch(e){error.value=explain(e)}}
async function loadOverview(){overview.value=(await api.get(base+'/overview')).data;if(!deviceId.value)deviceId.value=activeDevice.value?.id||''}
let freightStatusSequence=0,freightOutageObserved=false
async function loadFreightStatus(){
  const sequence=++freightStatusSequence
  try {
    const status=(await api.get('/api/freight/status')).data
    if(sequence!==freightStatusSequence)return
    if(status.availability==='unavailable')freightOutageObserved=true
    if(status.availability==='available' && freightOutageObserved){freightRestored.value=true;freightOutageObserved=false}
    if(status.availability!=='available')freightRestored.value=false
    if(status.availability==='configuration')freightOutageObserved=false
    freightStatus.value=status
  } catch {if(sequence===freightStatusSequence){freightStatus.value.availability='unknown';freightRestored.value=false}}
}
async function init(){try{await Promise.all([loadOverview(),loadAddresses(),api.get(base+'/senders').then(r=>senders.value=r.data),api.get(base+'/layouts').then(r=>layouts.value=r.data),loadFreightStatus()])}catch(e){error.value=explain(e)}}
function changeTab(t:string){tab.value=t;if(t==='history')loadHistory();if(t==='freight')loadFreights()}
function applyDashboardLink(){
  const value=(key:string)=>typeof route.query[key]==='string'?route.query[key] as string:''
  const requestedTab=value('tab')
  historyQuery.value=value('q').slice(0,100)
  historyStatus.value=Object.hasOwn(states,value('status'))?value('status'):''
  historyOffset.value=0
  changeTab(tabs.some(t=>t.id===requestedTab)?requestedTab:'addresses')
  if(value('freight_id'))void openUsageFreight(value('freight_id'))
  if(value('action')==='print')openPrint(emptyForm())
}
watch(()=>route.query,applyDashboardLink)
function closeModal(){if(saving.value)return;modal.value='';modalError.value='';if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value=''}
function newAddress(){form.value=emptyForm();customerResults.value=[];customerQuery.value='';linkedName.value='';modal.value='address';modalError.value=''}
function editAddress(a:SavedAddress){form.value=clone(a);linkedName.value=a.cliente_nome || '';customerResults.value=[];modal.value='address';modalError.value=''}
let searchTimer:ReturnType<typeof setTimeout>|undefined;let searchSeq=0
function searchCustomers(){clearTimeout(searchTimer);const seq=++searchSeq;searchTimer=setTimeout(async()=>{try{const r=await api.get(base+'/customers',{params:{q:customerQuery.value}});if(seq===searchSeq)customerResults.value=r.data}catch(e){modalError.value=explain(e)}},300)}
function linkCustomer(c:Customer){form.value.customer_link_confirmed=true;form.value.cliente_id=c.kind==='pedidos'?c.id:null;form.value.pdv_cliente_id=c.kind==='pdv'?c.id:null;linkedName.value=c.nome;form.value.data.nome ||= c.nome;form.value.data.telefone ||= c.telefone||'';form.value.data.cpf ||= c.cpf||'';form.value.data.endereco ||= c.endereco||'';customerResults.value=[];customerQuery.value=''}
async function saveAddress(){await act(async()=>{const {id,label,data,cliente_id,pdv_cliente_id,active,version}=form.value;const body={label,data,cliente_id,pdv_cliente_id,active,version,customer_link_confirmed:form.value.customer_link_confirmed || false};const response=id?await api.put(base+'/addresses/'+id,body):await api.post(base+'/addresses',body);modal.value='';notice.value=response.data.reused?'Endereço já existente reutilizado. O histórico foi preservado.':'Endereço salvo.';await Promise.all([loadAddresses(),loadOverview()])})}
function openAddressUsage(a:SavedAddress){usageAddress.value=a;modal.value='address-usage';modalError.value=''}
async function openUsageFreight(id:string){await act(async()=>{selectedFreight.value=(await api.get('/api/freight/orders/'+id)).data;modal.value='freight-result'})}
function openPrint(a:SavedAddress){form.value=clone(a);senderId.value='';parentId.value=null;requestKey.value=crypto.randomUUID();modal.value='print';modalError.value='';previewUrl.value=''}
function printBody(){return{request_key:requestKey.value,address_id:form.value.id||null,device_id:deviceId.value,sender_id:senderId.value||null,data:form.value.data,parent_id:parentId.value}}
async function previewPrint(){await act(async()=>{const r=await api.post(base+'/preview',printBody(),{responseType:'blob'});if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value=URL.createObjectURL(r.data)})}
async function submitPrint(){await act(async()=>{await api.post(base+'/print',printBody());modal.value='';notice.value='Uma cópia enviada à fila da loja.';await loadOverview();if(tab.value==='history')await loadHistory()})}
async function viewJob(id:string){await act(async()=>{const r=await api.get(base+'/history/'+id+'/pdf',{responseType:'blob'});const u=URL.createObjectURL(r.data);window.open(u,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(u),60000)})}
async function editJob(j:Job){await act(async()=>{const {data:d}=await api.get(base+'/history/'+j.id);const p=d.snapshot;form.value={...emptyForm(),label:p.endereco.nome||'Endereço',data:p.editor||{...blankAddress(p.endereco.pais),...p.endereco}};delete (form.value.data as AddressData & {remetente?:string}).remetente;parentId.value=j.id;senderId.value=p.sender_id||p.endereco.remetente||'';deviceId.value=d.device_id;requestKey.value=crypto.randomUUID();modal.value='print'})}
async function cancelJob(id:string){await act(async()=>{await api.post(base+'/history/'+id+'/cancel');await Promise.all([loadHistory(),loadOverview()])})}
async function generatedSenderSaved(){generatorOpen.value=false;await act(async()=>{senders.value=(await api.get(base+'/senders')).data;notice.value='Remetente salvo após sua aprovação, com origem sintética identificada.'})}
function newSender(){senderForm.value={id:'',name:'',lines:[],data:null,active:true,version:1};senderData.value=blankAddress('BR');modal.value='sender';modalError.value=''}
function editSender(s:Sender){senderForm.value=clone(s);senderData.value=s.data?clone(s.data):{...blankAddress('BR'),nome:s.name};modal.value='sender';modalError.value=''}
async function saveSender(){await act(async()=>{const {id,name,active,version}=senderForm.value;const b={name,active,version,lines:senderBlock.value,data:{...senderData.value,nome:senderData.value.nome||senderForm.value.name}};if(id)await api.put(base+'/senders/'+id,b);else await api.post(base+'/senders',b);senders.value=(await api.get(base+'/senders')).data;modal.value='';notice.value='Remetente salvo. Novas impressões usarão os dados atualizados.'})}
function moveField(l:Layout,i:number,delta:number){const next=[...l.config.fields];[next[i],next[i+delta]]=[next[i+delta]!,next[i]!];l.config.fields=next}
function addField(l:Layout,event:Event){const el=event.target as HTMLSelectElement;if(el.value)l.config.fields.push(el.value);el.value=''}
async function saveLayout(l:Layout){await act(async()=>{const r=await api.put(base+'/layouts/'+l.id,{name:l.name,config:l.config,version:l.version});l.version=r.data.version;notice.value='Padrão salvo para novas impressões do ERP e do bot.'})}
function openFreight(a:SavedAddress){form.value=clone(a);senderId.value='';requestKey.value=crypto.randomUUID();modal.value='freight';modalError.value=''}
async function quoteFreight(){await act(async()=>{selectedFreight.value=(await api.post('/api/freight/quotes',{request_key:requestKey.value,address_id:form.value.id,sender_id:senderId.value,package:packageForm.value,products:products.value,non_commercial:nonCommercial.value,invoice:invoice.value})).data;modal.value='freight-result';await loadFreights()})}
async function createCart(service:number){await act(async()=>{selectedFreight.value=(await api.post('/api/freight/orders/'+selectedFreight.value!.id+'/cart',{service})).data;await loadFreights()})}
async function payFreight(){await act(async()=>{selectedFreight.value=(await api.post('/api/freight/orders/'+selectedFreight.value!.id+'/pay',{expected_price:selectedFreight.value!.price,auto_print:autoPrintLabel.value,device_id:deviceId.value||null})).data;await loadFreights()})}
async function refreshFreight(f:Freight){await act(async()=>{selectedFreight.value=(await api.post('/api/freight/orders/'+f.id+'/refresh')).data;await loadFreights()})}
async function openLabelPdf(){await act(async()=>{const data=(await api.get('/api/freight/orders/'+selectedFreight.value!.id+'/pdf',{responseType:'blob'})).data;const url=URL.createObjectURL(data);const a=document.createElement('a');a.href=url;a.download=tr('etiqueta.pdf');a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)})}
async function printLabel(){await act(async()=>{const id=selectedFreight.value!.id;const key=labelRequestKeys.get(id)||crypto.randomUUID();labelRequestKeys.set(id,key);await api.post('/api/freight/orders/'+id+'/print',{device_id:deviceId.value,request_key:key});labelRequestKeys.delete(id);notice.value='Etiqueta enviada à impressora.';modal.value='';await loadOverview()})}
let timer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{init();applyDashboardLink();timer=setInterval(()=>{loadOverview().catch(()=>{});if(tab.value==='history')loadHistory();if(tab.value==='freight'||modal.value==='freight-result')loadFreights()},10000)})
onUnmounted(()=>{freightStatusSequence++;clearInterval(timer);clearTimeout(searchTimer);if(previewUrl.value)URL.revokeObjectURL(previewUrl.value)})
</script>

